### Por qué falla el intervalo de Wald {#sec-ic-cobertura}

::: {.pregunta}
Si un intervalo dice ser del 95 %, ¿contiene al parámetro el 95 % de las veces?
:::

Para la media con datos normales, sí. Para una proporción con el intervalo de Wald, muchas veces no. La razón es que $\hat{p}$ solo puede tomar los valores $0, 1/n, 2/n, \dots, 1$, y la aproximación normal es mala cuando $p$ está cerca de 0 o de 1. El caso extremo es $x = 0$: el intervalo de Wald da $[0,\ 0]$, un intervalo de ancho cero que afirma que la proporción es exactamente cero.

La probabilidad real de que el intervalo contenga a $p$ se llama cobertura, y para una proporción se puede calcular exactamente: se suma la probabilidad binomial de cada resultado $x$ cuyo intervalo contiene a $p$. La @fig-ic-int-cobertura hace ese cálculo para los intervalos de Wilson (azul) y de Wald (naranja) en función del valor verdadero de $p$; los valores menores que 0.5 se dibujan en 0.5 [@agresti1998approximate].

::: {#fig-ic-int-cobertura}





```{=html}
<div class="interactivo" id="int-cobertura">
  <label><span>Tamaño de muestra <i>n</i>:</span> <output>30</output>
    <input type="range" min="5" max="200" step="1" value="30"></label>
  <p class="resultado"></p>
  <svg viewBox="0 0 640 300" role="img" aria-label="Cobertura real de los intervalos de Wald y de Wilson en función de la proporción verdadera"></svg>
</div>
<script>
(function () {
  var raiz = document.getElementById("int-cobertura");
  var cn = raiz.querySelector("input"), salida = raiz.querySelector("output");
  var texto = raiz.querySelector(".resultado"), svg = raiz.querySelector("svg");
  var w = 640, h = 300, m = 40, z = 1.959964;
  function lfact(k) { var s = 0; for (var i = 2; i <= k; i++) s += Math.log(i); return s; }
  var sx = function (p) { return m + p * (w - 2 * m); };
  var sy = function (c) { return h - m - (c - 0.5) / 0.5 * (h - 2 * m); };
  function dibujar() {
    var n = parseInt(cn.value, 10); salida.textContent = n;
    var lf = []; for (var k = 0; k <= n; k++) lf.push(lfact(k));
    var wald = [], wil = [];
    for (var x = 0; x <= n; x++) {
      var ph = x / n, e = z * Math.sqrt(ph * (1 - ph) / n);
      wald.push([ph - e, ph + e]);
      var den = 1 + z * z / n, cen = (ph + z * z / (2 * n)) / den,
          mar = z * Math.sqrt(ph * (1 - ph) / n + z * z / (4 * n * n)) / den;
      wil.push([cen - mar, cen + mar]);
    }
    var dW = "", dV = "", sW = 0, sV = 0, k = 0;
    for (var p = 0.005; p < 0.9951; p += 0.005) {
      var cW = 0, cV = 0, lp = Math.log(p), lq = Math.log(1 - p);
      for (var x2 = 0; x2 <= n; x2++) {
        var pr = Math.exp(lf[n] - lf[x2] - lf[n - x2] + x2 * lp + (n - x2) * lq);
        if (wald[x2][0] <= p && p <= wald[x2][1]) cW += pr;
        if (wil[x2][0] <= p && p <= wil[x2][1]) cV += pr;
      }
      sW += cW; sV += cV; k++;
      dW += (dW ? "L" : "M") + sx(p).toFixed(1) + "," + sy(Math.max(cW, 0.5)).toFixed(1);
      dV += (dV ? "L" : "M") + sx(p).toFixed(1) + "," + sy(Math.max(cV, 0.5)).toFixed(1);
    }
    var ejes = "";
    for (var i = 0; i <= 10; i += 2) ejes += '<text class="eje-texto" x="' + sx(i / 10) + '" y="' + (h - m + 18) + '" text-anchor="middle">' + (i / 10).toFixed(1) + '</text>';
    [0.5, 0.6, 0.7, 0.8, 0.9, 1].forEach(function (c) { ejes += '<text class="eje-texto" x="' + (m - 6) + '" y="' + (sy(c) + 4) + '" text-anchor="end">' + c.toFixed(1) + '</text>'; });
    svg.innerHTML = '<line class="eje" x1="' + m + '" x2="' + (w - m) + '" y1="' + (h - m) + '" y2="' + (h - m) + '"/>' +
      '<line class="eje" x1="' + m + '" x2="' + m + '" y1="' + sy(1) + '" y2="' + (h - m) + '"/>' + ejes +
      '<line class="guia" x1="' + m + '" x2="' + (w - m) + '" y1="' + sy(0.95) + '" y2="' + sy(0.95) + '"/>' +
      '<path class="curva-2" d="' + dW + '"/><path class="curva" d="' + dV + '"/>' +
      '<text class="eje-texto" x="' + (w / 2) + '" y="' + (h - 4) + '" text-anchor="middle">Proporción verdadera p</text>' +
      '<text class="eje-texto" x="' + (m + 8) + '" y="' + (sy(1) + 4) + '">Cobertura real</text>';
    texto.innerHTML = "Cobertura promedio sobre todos los valores de <i>p</i>: Wilson (azul) = <b>" + (sV / k).toFixed(3) +
      "</b>; Wald (naranja) = <b>" + (sW / k).toFixed(3) + "</b>. Nominal: 0.950 (línea discontinua).";
  }
  cn.addEventListener("input", dibujar);
  dibujar();
})();
